import{_ as i,a0 as m,w as p,s as l,ao as e,I as n,x as a,a1 as o,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Linux vmstat 命令 - 报告虚拟内存统计的工具 | LCTT x X-CMD","titleTemplate":false,"description":"Linux vmstat 命令 - 报告虚拟内存统计的工具 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux vmstat 命令 - 报告虚拟内存统计的工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux vmstat 命令 - 报告虚拟内存统计的工具 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/Linux vmstat Command - Tool to Report Virtual Memory Statistics","title":"Linux vmstat 命令 - 报告虚拟内存统计的工具","tag":"201401","desc":""},"relativePath":"201401/Linux vmstat Command - Tool to Report Virtual Memory Statistics.md","filePath":"[post].md"}'),d={name:"201401/Linux vmstat Command - Tool to Report Virtual Memory Statistics.md"};function g(h,t,u,v,x,c){const s=m("Link");return p(),l("div",null,[t[14]||(t[14]=e('<h1 id="linux-vmstat-命令-报告虚拟内存统计的工具" tabindex="-1">Linux vmstat 命令 - 报告虚拟内存统计的工具 <a class="header-anchor" href="#linux-vmstat-命令-报告虚拟内存统计的工具" aria-label="Permalink to “Linux vmstat 命令 - 报告虚拟内存统计的工具”">​</a></h1><p>众所周知，计算机必须有称之为RAM(随机访问内存)的存储器使得计算机工作。RAM指的是插在计算机主板上的物理存储。这里的RAM被用于加载像浏览器、文字处理器这类的程序，实际上，你使用的程序都运行在内存上。</p><p>让我们假设你有2GB的内存。当你在运行操作系统时，你的可用内存可能只有1.5GB。接着你使用了大量的程序。当内存使用满之后，你可能再也无法加载更多的程序。浅显地说，计算机可能会说:&quot;抱歉，你不能在运行更多的程序了，如果你还要运行其他的程序请先关闭一些程序。&quot;</p><p>为了解决这个问题，包括Linux在内的各种操作系统使用了一个称之为虚拟内存的方法。这个方法会搜索最近不在使用的程序的内存区域，接着将它们拷贝到计算机硬盘上。这会腾出一些剩余内存空间给你有机会运行更多的程序。</p><p>为了监视虚拟内存的活动，我们使用<strong>vmstat</strong>工具。</p><h3 id="什么是-vmstat" tabindex="-1">什么是 vmstat <a class="header-anchor" href="#什么是-vmstat" aria-label="Permalink to “什么是 vmstat”">​</a></h3><p>vmstat是一个提供报告虚拟内存统计的工具。它包括了系统内存、交换和实时处理器利用率。</p><h3 id="如何运行-vmstat" tabindex="-1">如何运行 vmstat <a class="header-anchor" href="#如何运行-vmstat" aria-label="Permalink to “如何运行 vmstat”">​</a></h3>',8)),n("p",null,[t[1]||(t[1]=a("和",-1)),o(s,{href:"http://linoxide.com/linux-command/linux-mpstat-command/"},{default:r(()=>[...t[0]||(t[0]=[a("mpstat",-1)])]),_:1}),t[2]||(t[2]=a("一样，vmstat包含在sysstat包中。如果你还没有，请安装sysstat包。",-1))]),t[15]||(t[15]=e(`<p>为了运行vmstat，只需在控制台输入vmstat。不带参数运行vmstat会显示vmstat的默认结果。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/vmstat_default.png" alt=""></p><p>让我们看下如何了解vmstat提供的信息：</p><h4 id="procs" tabindex="-1">Procs <a class="header-anchor" href="#procs" aria-label="Permalink to “Procs”">​</a></h4><p>procs有 <strong>r</strong>列和<strong>b</strong>列。<strong>r</strong>列代表等待访问CPU进程的数量。而b列意味着睡眠进程的数量。在这些列的下面，是它们的值。从上面的截图中，我门有2个进程正在等待访问CPU，0个睡眠进程。</p><h4 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to “Memory”">​</a></h4><p>memory有<strong>swpd、 free、 buff</strong> 和 <strong>cache</strong> 这些列。这些信息和命令<strong>free -m</strong>相同。<strong>swpd列</strong>显示了有多少内存已经被交换到了交换文件或者磁盘。<strong>free列</strong>显示了未分配的可用内存。<strong>buff列</strong>显示了使用中的内存。<strong>cache列</strong>显示了有多少内存可以被交换到交换文件或者磁盘上如果一些应用需要他们。</p><h4 id="swap" tabindex="-1">Swap <a class="header-anchor" href="#swap" aria-label="Permalink to “Swap”">​</a></h4><p>swap显示了从交换系统上发送或取回了多少内存。<strong>si</strong>列告诉我们每秒有多少内存被<strong>从swap移到真实内存</strong>中（In）。<strong>so</strong>列告诉我们每秒有多少内存被<strong>从真实内存移到swap</strong>中（Out）。</p><h4 id="i-o" tabindex="-1">I/O <a class="header-anchor" href="#i-o" aria-label="Permalink to “I/O”">​</a></h4><p><strong>io</strong>依据块的读写显示了每秒输入输出的活动。<strong>bi</strong>列告诉我们收到的块数量，<strong>bo</strong>列告诉我们发送的块数量。</p><h4 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to “System”">​</a></h4><p>system显示了每秒的系统操作数量。<strong>in</strong>列显示了系统每秒被中断的数量。<strong>cs</strong>列显示了系统为了处理所以任务而上下文切换的数量。</p><h4 id="cpu" tabindex="-1">CPU <a class="header-anchor" href="#cpu" aria-label="Permalink to “CPU”">​</a></h4><p>CPU告诉了我们CPU资源的使用情况。<strong>us列</strong>显示了处理器在非内核程序消耗的时间。<strong>sy列</strong>显示了处理器在内核相关任务上消耗的时间。<strong>id列</strong>显示了处理器的空闲时间。<strong>wa列</strong>显示了处理器在等待IO操作完成以继续处理任务上的时间。</p><h3 id="按间隔时间运行vmstat" tabindex="-1">按间隔时间运行vmstat <a class="header-anchor" href="#按间隔时间运行vmstat" aria-label="Permalink to “按间隔时间运行vmstat”">​</a></h3><p>作为一个统计工具，使用vmstat最好的方法是使用<strong>间隔时间</strong>。你可以间断地捕捉系统状态。让我假设以5秒的间隔运行vmstat。只需要在你的控制台中输入<strong>vmstat 5</strong>就行。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/vmstat_delay_5.png" alt=""></p><p>命令将会每5秒运行一次，<strong>直到</strong>你按下Ctrl-C来终止它。你也可以使用第二个参数来控制vmstat运行的次数。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/vmstat_count_7.png" alt=""></p><p>上面的命令会<strong>以5秒的间隔运行7次vmstat</strong>。</p><h3 id="显示活跃和非活跃内存" tabindex="-1">显示活跃和非活跃内存 <a class="header-anchor" href="#显示活跃和非活跃内存" aria-label="Permalink to “显示活跃和非活跃内存”">​</a></h3><p>要这么做，你可以在vmstat后加入<strong>-a</strong>选项。这是个示例。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/vmstat_a.png" alt=""></p><h3 id="显示磁盘统计数据总结" tabindex="-1">显示磁盘统计数据总结 <a class="header-anchor" href="#显示磁盘统计数据总结" aria-label="Permalink to “显示磁盘统计数据总结”">​</a></h3><p>如果你想，vmstat也可以打印系统磁盘活动统计。使用<strong>-D</strong>选项就行。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/vmstat_disk_sum.png" alt=""></p><h3 id="显示单位" tabindex="-1">显示单位 <a class="header-anchor" href="#显示单位" aria-label="Permalink to “显示单位”">​</a></h3><p>你可以选择你想打印的显示单位字符。在<strong>-S后跟上k (小写，1000)、 K (大写，1024)、 m (小写，1000000)、 M (大写，1048576)</strong> 字节. 如果你不想选择单位，默认使用的是K (1024)。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/vmstat_define_unit.png" alt=""></p><h3 id="显示某个磁盘分区的详细统计数据" tabindex="-1">显示某个磁盘分区的详细统计数据 <a class="header-anchor" href="#显示某个磁盘分区的详细统计数据" aria-label="Permalink to “显示某个磁盘分区的详细统计数据”">​</a></h3><p>要这么做，你可以使用<strong>-p选项跟上设备名</strong>。这里有个例子。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/vmstat_partition.png" alt=""></p><h3 id="文件" tabindex="-1">文件 <a class="header-anchor" href="#文件" aria-label="Permalink to “文件”">​</a></h3><p>vmstat实际上是使用这些文件获取的数据。</p><pre><code>/proc/meminfo
/proc/stat
/proc/*/stat 
</code></pre><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>如果你感觉系统运行超出内存了，在你增加物理内存前，这个工具可以帮助你确定问题的根本原因。通常上，你可以在控制台中输入<strong>man vmstat</strong>获取更多的关于vmstat的详细信息，这会为你显示vmstat的手册页。</p><hr>`,39)),n("p",null,[t[4]||(t[4]=a("via: ",-1)),o(s,{href:"http://linoxide.com/linux-command/linux-vmstat-command-tool-report-virtual-memory-statistics/"},{default:r(()=>[...t[3]||(t[3]=[a("http://linoxide.com/linux-command/linux-vmstat-command-tool-report-virtual-memory-statistics/",-1)])]),_:1})]),n("p",null,[t[7]||(t[7]=a("译者：",-1)),o(s,{href:"https://github.com/geekpi"},{default:r(()=>[...t[5]||(t[5]=[a("geekpi",-1)])]),_:1}),t[8]||(t[8]=a(" 校对：",-1)),o(s,{href:"https://github.com/wxy"},{default:r(()=>[...t[6]||(t[6]=[a("wxy",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=a("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[9]||(t[9]=[a("LCTT",-1)])]),_:1}),t[12]||(t[12]=a(" 原创翻译，",-1)),o(s,{href:"http://linux.cn/"},{default:r(()=>[...t[10]||(t[10]=[a("Linux中国",-1)])]),_:1}),t[13]||(t[13]=a(" 荣誉推出",-1))])])}const _=i(d,[["render",g]]);export{T as __pageData,_ as default};
